with parsed as (select id, plan, currency, tier_limits, tier_prices, discounts, element_at(tier_prices, 1) as entry_price, aggregate(tier_prices, cast(0 as double), (acc, p) -> acc + p, acc -> round(acc / size(tier_prices), 2)) as avg_tier_price, slice(tier_limits, 1, 2) as first_two_limits from price_tiers where currency = 'EUR') select plan, case when entry_price >= 30 then 'PREMIUM' else 'STANDARD' end as entry_price_tier, count(*) filter (where currency = 'EUR') as eur_rows, count_if(plan = 'pro') as pro_events, count(distinct plan) as distinct_plans, size(collect_set(plan)) as num_plans, round(sum(entry_price) / nullif(count(case when plan = 'starter' then 1 end), 0), 2) as entry_price_per_starter, round(avg(entry_price), 2) as avg_entry_price from parsed group by 1, 2 having count_if(plan = 'pro') >= 1 order by entry_price_per_starter desc nulls first;
